using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread sauce\n4. Add mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Eggs, Pecorino Romano, Guanciale, Black pepper", Steps = "1. Cook pasta al dente\n2. Fry guanciale until crisp\n3. Mix eggs and cheese\n4. Toss hot pasta with guanciale\n5. Add egg mixture off heat\n6. Season with pepper", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken\n3. Sauté onion, garlic, ginger\n4. Add tomato sauce and spices\n5. Simmer, add cream\n6. Add chicken pieces", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Eggs", Steps = "1. Soak noodles in warm water\n2. Press and cube tofu\n3. Make pad thai sauce\n4. Stir-fry tofu until golden\n5. Add eggs, then noodles\n6. Toss with sauce and garnish", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm taco shells\n5. Assemble with toppings", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Onion, Jalapeño, Salt, Tomato", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Mix in lime juice and salt\n4. Fold in diced onion, tomato, cilantro\n5. Add jalapeño to taste", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken, Bamboo shoots, Thai basil, Fish sauce, Sugar", Steps = "1. Heat coconut cream until oil separates\n2. Fry curry paste\n3. Add chicken, cook through\n4. Pour in coconut milk\n5. Add vegetables and bamboo shoots\n6. Season and add basil", AverageRating = 4.4, RatingCount = 9 },
        new Recipe { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken, Butter, Tomato puree, Cream, Garam masala, Kasuri methi, Ginger, Garlic", Steps = "1. Marinate chicken in yogurt and spices\n2. Cook chicken in tandoor or oven\n3. Make sauce with butter, tomato, spices\n4. Simmer sauce until thick\n5. Add cream and kasuri methi\n6. Add chicken pieces", AverageRating = 4.9, RatingCount = 25 },
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

